/** TAC4/TAC8: only audio generated by macOS say. Never point this at personal audio. */
import { chromium, expect } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";
import { performance } from "node:perf_hooks";
const root = "/tmp/workbench-phase-t-synthetic";
const browser = await chromium.launch();
const context = await browser.newContext({ baseURL: "http://127.0.0.1:8787", viewport: { width: 1440, height: 900 }, acceptDownloads: true });
const page = await context.newPage();
let attachment;
try {
  await page.goto("http://127.0.0.1:8787/");
  await expect(page.getByRole("button", { name: "Choose model" })).toContainText(/Qwen|Gemma|GPT|Llama/);
  const engine = await (await context.request.get("/api/transcription/status")).json();
  if (!engine.ready || engine.version.startsWith("fake")) throw new Error("The real engine must be configured and ready");
  const started = performance.now();
  const uploaded = page.waitForResponse((response) => response.url().endsWith("/api/attachments") && response.request().method() === "POST");
  await page.locator('input[type="file"]').setInputFiles(`${root}/say-synthetic.wav`);
  const response = await uploaded;
  if (response.status() !== 201) throw new Error(`Upload failed: ${response.status()}`);
  attachment = await response.json();
  const uploadSeconds = (performance.now() - started) / 1000;
  const chip = page.getByTestId("audio-chip").filter({ hasText: "say-synthetic.wav" });
  await expect(chip.getByRole("button", { name: "Open transcript for say-synthetic.wav" })).toBeVisible({ timeout: 120000 });
  await expect(chip).toContainText(/words.*tokens/);
  await chip.screenshot({ path: "../artifacts/phase-t/real-say-chip-1440.png" });
  await chip.getByRole("button", { name: "Open transcript for say-synthetic.wav" }).click();
  const panel = page.locator('[data-slot="sheet-content"]');
  await expect(panel.getByRole("button", { name: "Copy", exact: true })).toBeInViewport({ ratio: .9 });
  await expect(panel.locator("pre")).toContainText(/synthetic/i);
  await panel.screenshot({ path: "../artifacts/phase-t/real-say-text-1440.png", animations: "disabled" });
  await panel.getByRole("button", { name: "Timestamps", exact: true }).click();
  await expect(panel.locator("ol li").first()).toBeVisible();
  await panel.screenshot({ path: "../artifacts/phase-t/real-say-timestamps-1440.png", animations: "disabled" });
  const downloads = {};
  for (const format of ["text", "subtitles (.srt)", "details (.json)"]) {
    await panel.getByRole("button", { name: "Download", exact: true }).click();
    const pending = page.waitForEvent("download");
    await page.getByRole("menuitem", { name: `Download ${format}`, exact: true }).click();
    const download = await pending;
    const path = await download.path();
    const content = await readFile(path, "utf8");
    if (!content.length) throw new Error("Empty transcript download");
    if (format.includes("json") && !JSON.parse(content).segments.length) throw new Error("Invalid transcript JSON");
    if (format.includes("srt") && !content.includes(" --> ")) throw new Error("Invalid subtitles");
    downloads[format] = { bytes: Buffer.byteLength(content), opened: true };
  }
  const transcript = await (await context.request.get(`/api/attachments/${attachment.id}/transcript`)).json();
  await writeFile("../artifacts/phase-t/real-engine-check.json", JSON.stringify({ synthetic: true, engine_version: engine.version, upload_seconds: uploadSeconds, wall_seconds: (performance.now() - started) / 1000, transcript: { duration_seconds: transcript.attachment.transcript.duration_seconds, word_count: transcript.attachment.transcript.word_count, token_estimate: transcript.attachment.transcript.token_estimate, elapsed_seconds: transcript.attachment.transcript.elapsed_seconds, speed_x_realtime: transcript.attachment.transcript.speed_x_realtime, segment_count: transcript.segments.length }, downloads }, null, 2) + "\n");
  await page.getByRole("button", { name: "Close transcript" }).click();
  await context.request.delete(`/api/attachments/${attachment.id}`);
  attachment = undefined;
  const file = await readFile(`${root}/say-long-synthetic.wav`);
  const uploadedLong = await context.request.post("/api/attachments", { multipart: { file: { name: "say-long-synthetic.wav", mimeType: "audio/wav", buffer: file } } });
  if (uploadedLong.status() !== 201) throw new Error("Cancel fixture upload failed");
  attachment = await uploadedLong.json();
  const processes = () => { try { return execFileSync("pgrep", ["-f", attachment.id], { encoding: "utf8" }).trim(); } catch { return ""; } };
  let observed = "";
  for (let i = 0; i < 100 && !observed; i++) { observed = processes(); if (!observed) await new Promise((resolve) => setTimeout(resolve, 50)); }
  if (!observed) throw new Error("The real engine child was not observed");
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const before = processes();
  await context.request.post(`/api/attachments/${attachment.id}/cancel`, { data: {} });
  const after = processes();
  const cancelled = (await (await context.request.get("/api/attachments/pending")).json()).find((item) => item.id === attachment.id);
  if (after || cancelled?.transcript?.status !== "cancelled") throw new Error("A cancelled engine child remained");
  const globalProcesses = {};
  for (const program of ["ffmpeg", "whisper-cli"]) { try { globalProcesses[program] = execFileSync("pgrep", ["-x", program], { encoding: "utf8" }).trim(); } catch { globalProcesses[program] = "no matches"; } }
  await writeFile("../artifacts/phase-t/cancellation.json", JSON.stringify({ synthetic: true, command: "pgrep -f <synthetic attachment uuid>", before_pids: before || observed, after: after || "no matches", global_process_check: globalProcesses, status: cancelled.transcript.status }, null, 2) + "\n");
  await context.request.delete(`/api/attachments/${attachment.id}`);
  const removed = await context.request.get(`/api/attachments/${attachment.id}`);
  if (removed.status() !== 404) throw new Error("Remove did not delete the file");
  console.log("Real say transcription, all three UI downloads, and subprocess cancellation passed.");
} finally {
  if (attachment) await context.request.delete(`/api/attachments/${attachment.id}`).catch(() => {});
  await browser.close();
}
